const input = $input.first().json ?? {};
const productId = input.product_id;

if (productId === undefined || productId === null || String(productId).trim() === '') {
  return [{ json: { error: 'missing_product_id', collections: [], collection_titles: [] } }];
}

return [{ json: { gid: `gid://shopify/Product/${productId}` } }];

// Se ejecuta despues de la llamada GraphQL. Con continueOnFail=true en ese nodo,
// un error de red/HTTP llega aca como { error: {...} } en vez de cortar el workflow --
// en ese caso (y ante cualquier otra forma de respuesta inesperada, incluyendo errores
// a nivel GraphQL en vez de HTTP) se devuelve una lista vacia en vez de tumbar la
// creacion/actualizacion del producto completa por un problema en este enriquecimiento
// adicional, que es secundario al guardado del producto en si.
const input = $input.first().json ?? {};

if (input.error) {
  return [{ json: { collections: [], collection_titles: [], warning: 'graphql_call_failed' } }];
}

const graphqlErrors = input.errors;
if (Array.isArray(graphqlErrors) && graphqlErrors.length > 0) {
  return [{ json: { collections: [], collection_titles: [], warning: 'graphql_errors', detail: graphqlErrors } }];
}

const edges = input?.data?.product?.collections?.edges ?? [];
const collections = edges.map((e) => ({
  id: e.node?.id ?? null,
  title: e.node?.title ?? null,
  handle: e.node?.handle ?? null
})).filter((c) => c.title);

return [{ json: { collections, collection_titles: collections.map((c) => c.title) } }];

